function UISystemGuideDescNode:FreshDialogPos(actionNode, renderCameraType)
    if isNull(actionNode) then
        self.DialogNode.anchoredPosition = Vector2(0, 0)
    elseif checkNumber(renderCameraType) >= Constants.GuideNodeCameraType.MainCamera then
        local v2 = CfUtils.WorldPosition2UIPosition(actionNode.position, self.DialogNode.transform.parent)
        self.DialogNode.anchoredPosition = v2
    else
        self.DialogNode.position = actionNode.position

    end
end

function UISystemGuideDescNode:FreshUI(text, dialogPos, dialogLineDirection)
    local isConfigDialogText = not string.isEmpty(text)
    KTool.SetActive(self.controller.gameObject, isConfigDialogText)
    
    if not isConfigDialogText then return end

    self.TxtDescription.text = string.gsub(text, "\\n", "\n")

    if not Tools.isNullKey(dialogPos) then
        local dialogStr, rolePosStr = SafeUnpack(parse_strings(dialogPos, "||"))

        local x, y = SafeUnpack(parse_strings(dialogStr, ";"))
        local anchoredPosition = self.DialogNode.anchoredPosition3D
        self.DialogNode.anchoredPosition3D = Vector3.New(anchoredPosition.x + checkNumber(x), anchoredPosition.y + checkNumber(y), 0)

        local isShowRole = not Tools.isNullKey(rolePosStr)
        KTool.SetActive(self.RoleNode.gameObject, isShowRole)
        if isShowRole then
            self:StopSpineCo()
            self.spineCo = cs_coroutine.start(function ()
                local track = self.SpineRole.AnimationState:SetAnimation(0, "play2", false);
                cs_coroutine.yield_return(WaitForSpineAnimationComplete(track));
                self.SpineRole.AnimationState:SetAnimation(0, "idle", true);
            end)

        end
        -- KTool.SetActive(self.RawImageTrans.gameObject, isShowRole)
        -- self.RawImageTrans.anchoredPosition3D = Vector3.zero
        -- if isShowRole then
        --     local x, y = SafeUnpack(parse_strings(rolePosStr, ";"))
        --     local anchoredPosition = self.RawImageTrans.anchoredPosition3D
        --     self.RawImageTrans.anchoredPosition3D = Vector3.New(anchoredPosition.x + checkNumber(x), anchoredPosition.y + checkNumber(y), 0)
        -- end
        self.AIRoleDialogUiSwitch.Status = isShowRole and 1 or 2
    end

end

function UISystemGuideDescNode:StopSpineCo()
    if self.spineCo == nil then
        return
    end
    cs_coroutine.stop(self.spineCo)
    
end

